-- Food, water and pet food: pure data and logic, no WoW globals.
-- Data/Supplies.lua (generated by tools/build_supplies.py) maps an item id to an item mask:
--   bit 0 food, bit 1 drink, bits 2-7 pet diets (Meat, Fish, Bread, Cheese, Fruit, Fungus), bit 8 healthstone.
-- A vendor's supply mask is the OR of its items' masks over bits 0-7 (see Discovery.lua). Bit numbers are
-- permanent. Plain arithmetic, no bit library.
local _, ns = ...

local L = ns.L
local S = {}
ns.Supplies = S

S.FOOD, S.WATER, S.HEALTHSTONE = 1, 2, 256
S.DIETS = { "Meat", "Fish", "Bread", "Cheese", "Fruit", "Fungus" }
local DIET_BIT = {}
for i, d in ipairs(S.DIETS) do DIET_BIT[d] = 2 ^ (i + 1) end
S.DIET_BIT = DIET_BIT

-- The sounds a reminder can play: { saved key, game sound id, label }. The setting saves the key, never
-- the id; "none" is silent. Ids are the game's own sound ids (PlaySound).
S.SOUNDS = {
    { "whisper", 3081, L["Whisper ping"] },
    { "ping", 3175, L["Minimap ping"] },
    { "invite", 880, L["Group invite"] },
    { "ready", 8960, L["Ready check"] },
    { "none", nil, L["None"] },
}
S.DEFAULT_SOUND = "whisper"

-- The sound id for a saved key; an unknown key gets the default, "none" gets nothing.
function S.SoundId(key)
    for _, s in ipairs(S.SOUNDS) do if s[1] == key then return s[2] end end
    return S.SoundId(S.DEFAULT_SOUND)
end

-- The saved key a player means by text (the key or the label, case ignored); nil if none.
function S.FindSound(text)
    local want = tostring(text or ""):lower():gsub("^%s+", ""):gsub("%s+$", "")
    for _, s in ipairs(S.SOUNDS) do
        if s[1] == want or s[3]:lower() == want then return s[1] end
    end
end

-- Classes that use mana, so drink.
local MANA = { MAGE = true, PRIEST = true, PALADIN = true, SHAMAN = true, DRUID = true, WARLOCK = true, HUNTER = true }
function S.UsesMana(class) return MANA[class] == true end

local function has(mask, bit) return math.floor((mask or 0) / bit) % 2 == 1 end
local function items() return ns.SupplyItems or {} end

-- The item mask of an item id (0 for an item that is not a supply).
function S.ItemMask(id) return items()[id] or 0 end

-- OR of two masks below 512.
function S.Or(a, b)
    local out = 0
    for i = 0, 8 do
        local bit = 2 ^ i
        if has(a, bit) or has(b, bit) then out = out + bit end
    end
    return out
end

-- Vendor supply mask for a set of offered item ids: the item masks ORed, bits 0-7 only.
function S.VendorMask(ids)
    local mask = 0
    for id in pairs(ids) do mask = S.Or(mask, S.ItemMask(id)) end
    return mask % 256
end

-- True when a vendor mask has any of the bits in `want` (a number that is a sum of distinct bits).
function S.Sells(mask, want)
    for i = 0, 7 do
        local bit = 2 ^ i
        if has(want, bit) and has(mask, bit) then return true end
    end
    return false
end

-- Bits of a set of diet names ({ Meat = true }); unknown names are ignored.
function S.DietBits(diets)
    local bits = 0
    for name in pairs(diets or {}) do bits = bits + (DIET_BIT[name] or 0) end
    return bits
end

-- The diets of a pet family id (UnitCreatureFamily's id, the same in every language) as a set of names
-- ({ Meat = true }), or nil for a family that is unknown or eats nothing. Data: ns.PetFamilies.
function S.FamilyDiets(id)
    local bits = (ns.PetFamilies or {})[id]
    if not bits then return end
    local set, any = {}, false
    for _, name in ipairs(S.DIETS) do
        if has(bits, DIET_BIT[name]) then set[name] = true; any = true end
    end
    return any and set or nil
end

-- What a vendor must sell for a supply key: "food", "water" or "pet" (the pet's diets). nil for none.
function S.Want(key, diets)
    if key == "food" then return S.FOOD end
    if key == "water" then return S.WATER end
    if key == "pet" then
        local bits = S.DietBits(diets)
        return bits > 0 and bits or nil
    end
end

-- Totals from the bag counts. counts: item id -> number, or nil when bags cannot be read. diets: the pet's
-- diet set or nil. Returns nil for unreadable bags, else { food, water, pet, healthstone } (pet is nil
-- without a diet). An item counts once toward each total, whatever number of diets match.
function S.Totals(counts, diets)
    if not counts then return nil end
    local want = S.DietBits(diets)
    local t = { food = 0, water = 0, healthstone = 0, pet = want > 0 and 0 or nil }
    for id, n in pairs(counts) do
        local m = items()[id]
        if m then
            if has(m, S.FOOD) then t.food = t.food + n end
            if has(m, S.WATER) then t.water = t.water + n end
            if has(m, S.HEALTHSTONE) then t.healthstone = t.healthstone + n end
            if t.pet and S.Sells(m % 256, want) then t.pet = t.pet + n end
        end
    end
    return t
end

local function anySpell(list, knows)
    for _, s in ipairs(list or {}) do if knows(s) == true then return true end end
    return false
end

-- The spells that conjure food and water (mage) or create a healthstone (warlock), read from the
-- display-only reagent entries.
local function spellsOf(class, itemId)
    for _, item in ipairs(ns.Reagents.DisplayOnly(class)) do
        if item.id == itemId then return item.spells end
    end
end

-- What is low or worth a reminder. in: { class, totals (S.Totals or nil), knows(spellId) -> true/false/nil,
-- cfg = { foodEnabled, waterEnabled, petFoodEnabled, healthstoneRemind, foodThreshold, waterThreshold,
-- petFoodThreshold } }. Returns { go = { { key, count } }, remind = { { key, count } } } in the order food,
-- water, pet. A mage who knows the conjure spell is reminded instead of sent; a warlock without a
-- healthstone is reminded. An unreadable count is never low.
function S.Evaluate(class, totals, knows, cfg)
    local out = { go = {}, remind = {} }
    if not totals then return out end
    local function check(key, enabled, threshold, conjure)
        local n = totals[key]
        if not (enabled and n and n <= threshold) then return end
        if conjure and anySpell(spellsOf("MAGE", conjure), knows) and class == "MAGE" then
            out.remind[#out.remind + 1] = { key = key, count = n }
        else
            out.go[#out.go + 1] = { key = key, count = n }
        end
    end
    check("food", cfg.foodEnabled, cfg.foodThreshold, 5349)
    if S.UsesMana(class) then check("water", cfg.waterEnabled, cfg.waterThreshold, 5350) end
    if class == "HUNTER" then check("pet", cfg.petFoodEnabled, cfg.petFoodThreshold) end
    if class == "WARLOCK" and cfg.healthstoneRemind and totals.healthstone == 0
            and anySpell(spellsOf("WARLOCK", 6265), knows) then
        out.remind[#out.remind + 1] = { key = "healthstone", count = 0 }
    end
    return out
end
